-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial threshold application
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Plastics Inc., the engagement team identifies a $350 misstatement in office supplies expense. The overall materiality for the audit is $75,000, and the clearly trivial threshold is set at $3,750. Under AU-C 450, the auditor should:', '["Disregard the misstatement because it is below the clearly trivial threshold", "Accumulate the misstatement and include it on the summary of uncorrected misstatements", "Report the misstatement to those charged with governance as a significant finding", "Adjust the clearly trivial threshold downward to capture the misstatement"]'::jsonb, 0, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial—amounts clearly inconsequential whether taken individually or in the aggregate. Because $350 falls below the $3,750 threshold, Meridian''s auditor may disregard it. Choice B is incorrect because accumulation is only required for misstatements above the clearly trivial threshold, not below it.', 'medium', 2),

-- Q2: medium / L2 — Prior-period uncorrected misstatements effect on current year
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Ashford Timber Co., the auditor identified $18,000 in uncorrected misstatements that understated cost of goods sold. Management elected not to correct them. In planning the current-year audit, the auditor should:', '["Ignore the prior-year misstatements because they were evaluated in the previous audit", "Consider the effect of the prior-year uncorrected misstatements on the current year''s financial statements", "Require management to restate the prior-year financial statements before continuing", "Automatically increase the current-year materiality by the amount of the prior-year misstatements"]'::jsonb, 1, 'Under AU-C 450.12, the auditor must evaluate the effect of uncorrected misstatements from prior periods on the current period''s financial statements because these misstatements may reverse or persist, affecting the current year. Choice A is incorrect because prior-year uncorrected misstatements do not simply expire; their carryforward effect must be evaluated as part of the current-year audit.', 'medium', 2),

-- Q3: easy / L1 — Deficiency in design vs. deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what distinguishes a deficiency in design from a deficiency in operation?', '["A deficiency in design occurs when a properly designed control is not implemented correctly", "A deficiency in operation occurs when the entity lacks sufficient resources to perform controls", "A deficiency in design occurs when a necessary control is missing or not properly designed to meet its objective", "A deficiency in operation occurs when management intentionally overrides an existing control"]'::jsonb, 2, 'Under AU-C 265.A1, a deficiency in design exists when a control necessary to meet a control objective is missing or is not suitably designed so that, even if the control operates as designed, it cannot prevent or detect misstatements on a timely basis. Choice A describes a deficiency in operation, not design, because the control exists but fails to function as intended during execution.', 'easy', 1),

-- Q4: medium / L2 — Iron curtain approach for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Electronics LLC has accumulated $22,000 in uncorrected misstatements from the current year and $14,000 carried forward from prior years. The balance sheet impact of all accumulated misstatements totals $36,000 against materiality of $40,000. Under AU-C 450, the auditor applying the iron curtain approach evaluates misstatements by:', '["Considering only the current-year misstatements of $22,000 against materiality", "Comparing the income statement effect of each year''s misstatements independently", "Projecting the accumulated misstatements to the full population for comparison", "Comparing the total accumulated balance sheet effect of $36,000 against materiality"]'::jsonb, 3, 'Under AU-C 450.A18, the iron curtain approach quantifies a misstatement based on the total amount by which the current-period balance sheet is misstated, regardless of when the misstatement originated. The $36,000 cumulative balance sheet effect is compared directly to materiality. Choice A reflects the rollover approach, which considers only the current-year originating amount rather than the cumulative balance sheet effect.', 'medium', 2),

-- Q5: medium / L2 — Management representation letter and uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Granite Peak Consulting, the auditor requests a written representation letter from management. Regarding uncorrected misstatements, AU-C 580 requires management to:', '["Acknowledge that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "Provide a detailed remediation plan for all uncorrected misstatements identified during the audit", "Certify that no misstatements exist in the financial statements beyond those corrected during the audit", "Confirm that all misstatements identified by the auditor have been corrected in the final financial statements"]'::jsonb, 0, 'Under AU-C 580.11, the auditor obtains a written representation from management that it believes the effects of uncorrected misstatements, summarized by the auditor, are immaterial individually and in the aggregate to the financial statements as a whole. Choice D is incorrect because the representation specifically addresses uncorrected misstatements that remain, not a claim that all misstatements have been corrected.', 'medium', 2),

-- Q6: medium / L3 — Qualitative factors in evaluating immaterial misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakewood Pharmaceuticals Inc., the auditor identifies a $5,000 misstatement in executive bonus accruals. Overall materiality is $200,000, and performance materiality is $150,000. However, the misstatement involves compensation of senior management. What is the most likely effect of this qualitative factor on the auditor''s evaluation?', '["The misstatement is automatically reclassified as material because it involves management compensation", "The auditor should consider whether the misstatement may be indicative of fraud or management bias, potentially elevating its significance beyond its quantitative amount", "The misstatement should be removed from the summary because it is below performance materiality", "The auditor must issue a qualified opinion because executive compensation misstatements always require modification"]'::jsonb, 1, 'Under AU-C 450.11, the auditor considers both quantitative and qualitative factors when evaluating misstatements. A misstatement involving management compensation may indicate bias or intentional manipulation, increasing its significance regardless of dollar amount. Choice A is incorrect because qualitative factors do not automatically make a misstatement material; they require the auditor''s professional judgment to assess overall significance.', 'medium', 3),

-- Q7: hard / L3 — Pervasive vs. not pervasive misstatement and opinion type
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestwood Manufacturing Corp., the auditor discovers uncorrected misstatements totaling $85,000 against materiality of $100,000. The misstatements affect accounts receivable, inventory, and cost of goods sold across multiple reporting periods. The auditor determines the misstatements are material to the financial statements. What is the most likely effect of the pervasiveness of these misstatements on the auditor''s opinion?', '["The auditor should issue a qualified opinion because the misstatements, while material, do not warrant an adverse opinion", "The auditor should issue an unmodified opinion with an emphasis-of-matter paragraph highlighting the pervasive nature", "The auditor should consider whether the misstatements are pervasive enough to warrant an adverse opinion rather than a qualified opinion", "The auditor should disclaim an opinion because pervasive misstatements indicate a scope limitation"]'::jsonb, 2, 'Under AU-C 705.08, when misstatements are both material and pervasive—affecting multiple accounts, elements, or periods—the auditor should issue an adverse opinion rather than a qualified opinion. The spread across receivables, inventory, and COGS over multiple periods indicates pervasiveness. Choice A is incorrect because a qualified opinion is appropriate only when misstatements are material but not pervasive to the financial statements as a whole.', 'hard', 3),

-- Q8: medium / L2 — Documentation requirements for accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Silverline Distribution LLC, the engagement team identifies 14 misstatements ranging from $1,200 to $8,500. Under AU-C 450, the auditor''s documentation of these misstatements should include:', '["Only those misstatements that exceed performance materiality", "A description of each misstatement along with management''s verbal acknowledgment", "Only misstatements that management has agreed to correct", "All accumulated misstatements identified during the audit, including those corrected by management and those remaining uncorrected"]'::jsonb, 3, 'Under AU-C 450.14, the auditor must document all misstatements accumulated during the audit, the basis for the auditor''s conclusion on whether uncorrected misstatements are material, and whether management corrected them. Choice A is incorrect because the auditor documents all misstatements above the clearly trivial threshold, not just those exceeding performance materiality.', 'medium', 2),

-- Q9: hard / L4 — IT general control deficiency as material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Financial Group, the auditor discovers that the company''s database administrator has unrestricted access to modify financial data without logging, and no independent review of database changes exists. This access has been in place for 18 months. Although no actual misstatements have been detected, the database processes $45 million in transactions annually. The auditor should evaluate this deficiency as:', '["A material weakness because the lack of access controls and logging over a system processing significant transaction volume creates a reasonable possibility that a material misstatement would not be prevented or detected on a timely basis", "A significant deficiency because no actual misstatements resulted from the unrestricted access", "A control deficiency that warrants communication to management but does not require escalation", "Not a control deficiency because the database administrator is a trusted employee with appropriate technical qualifications"]'::jsonb, 0, 'Under AU-C 265.A7, the auditor evaluates severity based on the magnitude of the potential misstatement and whether there is a reasonable possibility it could occur. Unrestricted, unlogged access to a system processing $45 million creates a reasonable possibility of material misstatement regardless of whether one has occurred. Choice B is incorrect because material weakness classification depends on the potential for misstatement, not whether an actual misstatement has been identified.', 'hard', 4),

-- Q10: medium / L2 — Tolerable misstatement in audit sampling
(1, 'Misstatements and Control Deficiencies', 'The auditor of Ridgeway Construction Inc. plans to test accounts receivable using audit sampling. The population totals $3.2 million, and overall materiality is $160,000. The auditor sets tolerable misstatement for the receivables account at $96,000. Under AU-C 530, tolerable misstatement in the context of audit sampling represents:', '["The maximum dollar amount of misstatement that can exist in the population without affecting the audit opinion", "The application of performance materiality to a particular sampling procedure, representing the maximum misstatement in the population that the auditor is willing to accept", "The total projected misstatement from the sample extrapolated to the full population", "The threshold below which individual misstatements are considered clearly trivial"]'::jsonb, 1, 'Under AU-C 530.05, tolerable misstatement is the application of performance materiality to a particular sampling procedure and represents the maximum amount of misstatement the auditor can accept in the population while still concluding the sample result supports the account balance. Choice D is incorrect because the clearly trivial threshold is a separate, much lower amount used to determine which misstatements need not be accumulated.', 'medium', 2),

-- Q11: hard / L4 — Management bias indicators in misstatement patterns
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northshore Capital Partners, the auditor observes that management corrected all misstatements that would have decreased net income but declined to correct three misstatements totaling $28,000 that increased net income. Materiality is $250,000. The auditor should assess whether this pattern:', '["Eliminates audit risk because management''s corrections demonstrate a commitment to accurate reporting", "Requires the auditor to increase the sample size for all remaining substantive procedures", "Indicates possible management bias that should be evaluated in the context of the financial statements taken as a whole, even though the uncorrected misstatements are individually and aggregately immaterial", "Warrants immediate withdrawal from the engagement because management is not acting in good faith"]'::jsonb, 2, 'Under AU-C 450.A22, the auditor considers whether a pattern of misstatements—such as selectively correcting only income-decreasing errors—suggests management bias. Even when amounts are below materiality, a directional pattern may signal intentional manipulation requiring further evaluation. Choice D is incorrect because a potential indicator of bias does not automatically require withdrawal; the auditor must first assess the implications and the misstatements'' aggregate effect.', 'hard', 4),

-- Q12: hard / L4 — PCAOB integrated audit combined deficiencies evaluation
(1, 'Misstatements and Control Deficiencies', 'During the integrated audit of Trident Systems Corp., a public company, the engagement team identifies two control deficiencies—one in revenue cutoff procedures and one in payroll authorization. Individually, neither rises to the level of a material weakness. However, together they affect the reliability of period-end financial reporting. Under PCAOB AS 2201, the engagement team should evaluate whether:', '["Each deficiency should be communicated separately to the audit committee without further analysis", "The payroll deficiency can be disregarded because payroll is typically a low-risk area", "The revenue cutoff deficiency alone should be reported as a significant deficiency", "The combination of the two deficiencies constitutes a material weakness because their aggregate effect on financial reporting reliability may create a reasonable possibility of material misstatement"]'::jsonb, 3, 'Under PCAOB AS 2201.69, the auditor must evaluate whether individually insignificant control deficiencies, in combination, constitute a significant deficiency or material weakness. When deficiencies together affect the reliability of period-end reporting, their combined effect may cross the material weakness threshold. Choice A is incorrect because the auditor must assess the interaction between deficiencies rather than evaluating each in isolation.', 'hard', 4),

-- Q13: easy / L1 — Clearly trivial definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does the term "clearly trivial" mean in the context of audit misstatements?', '["Misstatements that are clearly inconsequential, whether taken individually or in the aggregate", "Misstatements that fall below overall materiality but above performance materiality", "Misstatements that management has agreed to correct before the audit report is issued", "Misstatements that affect only disclosures rather than recognized amounts in the financial statements"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial means amounts that are clearly inconsequential whether individually or in the aggregate—a threshold well below materiality. The auditor need not accumulate clearly trivial misstatements. Choice B is incorrect because clearly trivial is substantially lower than both overall materiality and performance materiality; it is not defined by the gap between these two benchmarks.', 'easy', 1),

-- Q14: easy / L1 — Rollover approach definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the rollover approach to evaluating misstatements?', '["An approach that compares the total cumulative balance sheet misstatement against materiality", "An approach that quantifies a misstatement based on the amount originating in the current period", "An approach that projects known misstatements from the sample to the entire population", "An approach that evaluates misstatements by rolling forward prior-year adjusting entries"]'::jsonb, 1, 'Under AU-C 450.A17, the rollover approach quantifies a misstatement as the amount originating in the current-period income statement, without considering the cumulative balance sheet effect of prior-period misstatements. Choice A is incorrect because it describes the iron curtain approach, which instead measures the total amount by which the ending balance sheet is misstated regardless of when the misstatement arose.', 'easy', 1),

-- Q15: medium / L3 — Effect of misstatement on debt covenants
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Properties LLC, the auditor identifies $42,000 in uncorrected misstatements against materiality of $120,000. However, if the misstatements were corrected, the company''s debt-to-equity ratio would breach a bank loan covenant requiring the ratio to remain below 2.5:1. What is the most likely effect of this covenant consideration on the auditor''s evaluation?', '["The misstatements become immaterial because they are below the quantitative materiality threshold", "The auditor should increase overall materiality to prevent the covenant breach from occurring", "The auditor should consider the misstatements material in the context of the specific covenant, even though they are below overall materiality", "The auditor should report the covenant breach directly to the lender without consulting management"]'::jsonb, 2, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements considering both quantitative amounts and qualitative factors, including the effect on compliance with debt covenants. A misstatement that triggers a covenant breach may be material in context even when below overall materiality. Choice A is incorrect because quantitative immateriality alone does not override the qualitative significance of potential covenant violations.', 'medium', 3),

-- Q16: hard / L4 — Evaluate potential withdrawal from engagement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Stratton Medical Devices Inc., management refuses to correct identified misstatements totaling $175,000 against materiality of $200,000. The auditor also discovers indicators of possible fraudulent financial reporting in the same accounts. Management has been uncooperative with further inquiries, limiting access to supporting documentation. The auditor should evaluate whether:', '["A qualified opinion adequately addresses the situation because the misstatements are below materiality", "The auditor should accept the uncorrected misstatements and issue an unmodified opinion with an other-matter paragraph", "The auditor should reduce materiality to below $175,000 to force management to correct the misstatements", "Withdrawal from the engagement may be necessary because the combination of fraud indicators, management''s refusal to cooperate, and restricted access may indicate a breakdown in the auditor-client relationship"]'::jsonb, 3, 'Under AU-C 240.38, when the auditor encounters circumstances indicating possible fraud combined with management''s unwillingness to cooperate, the auditor should consider whether withdrawal is appropriate. The combination of near-material misstatements, fraud indicators, and restricted access raises serious concerns about management integrity. Choice A is incorrect because the proximity to materiality combined with fraud indicators and restricted access creates a situation far more serious than a simple below-materiality quantitative evaluation.', 'hard', 4),

-- Q17: medium / L3 — Misstatements detected vs. not detected by controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearview Logistics Corp., the accounts payable department identified and corrected a $32,000 duplicate payment through its routine reconciliation process. The auditor also identified a separate $18,000 overstatement in inventory that was not detected by any of the client''s controls. What is the most likely implication of these two findings?', '["The undetected inventory misstatement suggests a control deficiency because the entity''s controls failed to prevent or detect the error, while the corrected duplicate payment demonstrates effective controls over disbursements", "Both findings represent control deficiencies because any misstatement indicates a failure in the control environment", "Neither finding represents a control deficiency because both amounts are likely below materiality", "The corrected duplicate payment represents a more serious deficiency because it indicates the control allowed the error to occur initially"]'::jsonb, 0, 'Under AU-C 265.A3, a control deficiency exists when a control does not allow management to prevent or detect misstatements on a timely basis. The inventory error escaped all controls, indicating a deficiency. The duplicate payment was caught by the reconciliation process, demonstrating the control operated effectively. Choice B is incorrect because a misstatement detected and corrected by the entity''s own controls demonstrates that the control is functioning as designed.', 'medium', 3),

-- Q18: easy / L1 — Three categories of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what are the three types of misstatements that an auditor should consider?', '["Material misstatements, immaterial misstatements, and clearly trivial misstatements", "Factual misstatements, judgmental misstatements, and projected misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements", "Known misstatements, likely misstatements, and possible misstatements"]'::jsonb, 1, 'Under AU-C 450.A3, misstatements are classified as factual (no doubt about existence), judgmental (differences arising from management''s estimates the auditor considers unreasonable), and projected (the auditor''s best estimate of misstatement in populations extrapolated from sample results). Choice D is incorrect because it uses older terminology; AU-C 450 specifically defines the three categories as factual, judgmental, and projected.', 'easy', 1),

-- Q19: easy / L1 — Scope of controls evaluated for deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which controls does the auditor evaluate for deficiencies during a financial statement audit?', '["All controls within the entity''s internal control framework, including operational and compliance controls", "Only controls over financial reporting that are also subject to regulatory examination", "Controls relevant to the audit that the auditor identified during obtaining an understanding of internal control", "Only controls that were specifically selected for testing during the audit engagement"]'::jsonb, 2, 'Under AU-C 265.06, the auditor evaluates deficiencies in internal control identified during the audit—specifically controls relevant to the audit identified during the risk assessment process under AU-C 315. Choice A is incorrect because a financial statement audit does not require the auditor to evaluate all controls, including operational and compliance controls not relevant to financial reporting assertions.', 'easy', 1),

-- Q20: medium / L3 — Turnaround effect of prior period misstatements
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Westfield Dynamics Inc., the auditor identified a $55,000 overstatement of accounts receivable that management did not correct. In the current year, the receivable was collected and the overstatement naturally reversed. The auditor is evaluating the current year''s income statement. What is the most likely effect of the prior-year misstatement on the current-year financial statements?', '["No effect, because the receivable was collected and the misstatement no longer exists", "The current-year balance sheet is misstated but the income statement is not affected", "Both the current-year balance sheet and income statement are misstated by $55,000", "The current-year income statement is understated because the reversal of the prior-year overstatement reduced current-year revenue or created a current-year expense"]'::jsonb, 3, 'Under AU-C 450.A16, prior-period uncorrected misstatements can have a turnaround effect on the current period. The reversal of a $55,000 receivable overstatement decreases current-year income, causing the income statement to be understated even though the balance sheet error has cleared. Choice A is incorrect because although the balance sheet misstatement resolved, the reversal shifts the misstatement''s effect to the current-year income statement.', 'medium', 3),

-- Q21: easy / L1 — Communication of other deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom should the auditor communicate control deficiencies that are not significant deficiencies or material weaknesses?', '["Management at an appropriate level of responsibility", "Those charged with governance only", "The external regulatory authority overseeing the entity", "The entity''s internal audit department for remediation"]'::jsonb, 0, 'Under AU-C 265.11, the auditor communicates in writing or orally to management at an appropriate level of responsibility control deficiencies that are not significant deficiencies or material weaknesses but are of sufficient importance to merit management''s attention. Choice B is incorrect because AU-C 265 requires communication of significant deficiencies and material weaknesses to governance, while other deficiencies are directed to management.', 'easy', 1),

-- Q22: medium / L2 — Nature vs. magnitude when evaluating deficiency severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Manufacturing Inc., the auditor identifies that the accounts payable clerk can both approve and record vendor payments without independent review. Total disbursements processed through this role amount to $180,000 annually, and overall materiality is $500,000. Under AU-C 265, the auditor evaluates the severity of this control deficiency by considering:', '["Only the $180,000 annual disbursement volume compared to the $500,000 materiality threshold", "Both the nature of the deficiency as a segregation of duties failure and the magnitude of transactions that could be misstated", "Only whether an actual misstatement has resulted from the lack of segregation of duties", "Only the nature of the deficiency without considering the dollar amounts involved"]'::jsonb, 1, 'Under AU-C 265.A7, the severity of a control deficiency depends on both the magnitude of the potential misstatement and the nature of the financial statement items or disclosures involved. A segregation of duties failure is evaluated by its nature as a design flaw and the transaction volume at risk. Choice C is incorrect because the evaluation focuses on the potential for misstatement, not solely whether an actual misstatement has been identified.', 'medium', 2),

-- Q23: easy / L1 — Risk of management override of controls
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 240, why must the auditor always consider the risk of management override of internal controls?', '["Because management override only occurs in entities that are committing fraud", "Because regulatory agencies require specific testing for management override in every audit", "Because management override bypasses otherwise effective controls and creates the opportunity for fraudulent financial reporting", "Because management override eliminates the need for the auditor to test internal controls"]'::jsonb, 2, 'Under AU-C 240.31, management''s ability to override controls is a presumed fraud risk in every audit because management is in a unique position to perpetrate fraud by bypassing controls that otherwise appear to be operating effectively. Choice A is incorrect because management override is a risk factor that exists in all entities, not solely those committing fraud; the auditor addresses this risk through specific procedures regardless of fraud indicators.', 'easy', 1),

-- Q24: easy / L2 — Classifying a factual misstatement in practice
(1, 'Misstatements and Control Deficiencies', 'While testing a sample of 40 purchase orders at Brookfield Supplies Co., the auditor discovers that one purchase order for $4,200 was recorded at $4,800 due to a data entry error. Under AU-C 450, this $600 error is classified as:', '["A judgmental misstatement because it involves a difference in recorded amounts", "A projected misstatement because it was found through sampling", "A clearly trivial misstatement because it involves a single transaction", "A factual misstatement because there is no doubt the $600 overstatement exists"]'::jsonb, 3, 'Under AU-C 450.A3, a factual misstatement is one about which there is no doubt—the $600 data entry error is a verifiable, objective difference between the recorded amount and the correct amount. Although discovered through sampling, the $600 itself is factual. Choice B is incorrect because a projected misstatement is the auditor''s best estimate of misstatement in the population based on extrapolation, not the individual error found in the sample.', 'easy', 2),

-- Q25: medium / L3 — Pattern of small misstatements as possible fraud indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornton Aerospace Inc., the auditor discovers that journal entries totaling $12,000 were posted to reduce warranty expense at the end of each of the last four quarters. Each entry was below the clearly trivial threshold of $15,000 and was authorized by the same mid-level manager. Overall materiality is $500,000. What is the most likely implication of this pattern for the auditor''s assessment?', '["The pattern suggests possible intentional manipulation that the auditor should evaluate as a potential fraud indicator, even though individual amounts are below the clearly trivial threshold", "The entries should be disregarded because each individually falls below the clearly trivial threshold", "The auditor should aggregate the entries and report them only if the total exceeds overall materiality", "The auditor should accept the entries because management authorized each one through normal channels"]'::jsonb, 0, 'Under AU-C 240.35, the auditor considers whether misstatements may be indicative of fraud regardless of individual dollar amount. A pattern of similar entries below detection thresholds, consistently reducing the same expense and authorized by the same person, suggests possible intentional manipulation. Choice B is incorrect because the clearly trivial threshold is designed for isolated inconsequential errors, not for patterns that may indicate deliberate circumvention of controls.', 'medium', 3),

-- Q26: medium / L3 — Group audit component misstatements
(1, 'Misstatements and Control Deficiencies', 'During the group audit of Meridian Holdings Inc., a component auditor reports $38,000 in uncorrected misstatements from a subsidiary that represents 15% of group revenue. The group materiality is $250,000, and component materiality was set at $75,000. What is the most likely effect of the component misstatements on the group auditor''s evaluation?', '["The group auditor may disregard the component misstatements because they are below group materiality", "The group auditor must include the component''s uncorrected misstatements in the group-level summary and evaluate their aggregate effect alongside misstatements from other components", "The group auditor must require the component auditor to reduce component materiality until the misstatements are corrected", "The group auditor should communicate the misstatements directly to the subsidiary''s management without further evaluation"]'::jsonb, 1, 'Under AU-C 600.42, the group auditor requests the component auditor to communicate misstatements above the component clearly trivial threshold. The group auditor then aggregates these with misstatements from other components to evaluate the overall effect on the group financial statements. Choice A is incorrect because misstatements below group materiality at one component may, when combined with misstatements from other components, exceed group materiality in aggregate.', 'medium', 3),

-- Q27: medium / L3 — Ineffective monitoring as control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Ridge Manufacturing, the auditor determines that the company''s internal audit function performed testing of revenue controls during the year but management never reviewed the internal audit reports or addressed the three deficiencies identified. What is the most likely effect of management''s inaction on the auditor''s assessment of the control environment?', '["No effect, because the internal audit function performed its testing as designed", "The deficiencies identified by internal audit are automatically classified as material weaknesses", "Management''s failure to act on internal audit findings indicates a monitoring deficiency that the auditor should evaluate for its effect on the overall control environment", "The auditor should replace internal audit testing with additional substantive procedures for revenue"]'::jsonb, 2, 'Under AU-C 265.A5, the effectiveness of a control depends not only on its design and operation but also on management''s response to identified weaknesses. Ignoring internal audit findings represents a monitoring deficiency—a failure in the oversight component of COSO—that may elevate the severity of underlying control deficiencies. Choice A is incorrect because effective internal control requires that findings are acted upon; testing alone without follow-up does not constitute effective monitoring.', 'medium', 3),

-- Q28: medium / L2 — Subsequent event and misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'After the balance sheet date of December 31, 2025, but before the audit report date of March 10, 2026, the auditor of Brighton Textiles Inc. discovers that a major customer filed for bankruptcy on January 20, 2026. The customer owed Brighton $95,000 at year-end. Under AU-C 560, the auditor should evaluate this event as:', '["A nonadjusting subsequent event requiring footnote disclosure but no adjustment to recognized amounts", "An event that does not affect the financial statements because it occurred after the balance sheet date", "A subsequent event requiring the auditor to recalculate overall materiality for the current engagement", "An adjusting subsequent event providing evidence about conditions at the balance sheet date, potentially indicating a misstatement in the allowance for doubtful accounts"]'::jsonb, 3, 'Under AU-C 560.09, events occurring after the balance sheet date that provide additional evidence about conditions existing at year-end are adjusting events. A customer''s January bankruptcy likely reflects deteriorating financial condition that existed at December 31, indicating the receivable and allowance may be misstated. Choice A is incorrect because a nonadjusting event relates to conditions arising after the balance sheet date, whereas deteriorating creditworthiness typically predates the formal bankruptcy filing.', 'medium', 2),

-- Q29: easy / L1 — Timing of AU-C 265 written communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, when must the auditor communicate significant deficiencies and material weaknesses in writing to those charged with governance?', '["No later than 60 days following the release of the auditor''s report", "Within 30 days of identifying the deficiency during fieldwork", "Before the audit engagement letter is signed for the following year", "Simultaneously with the issuance of the management representation letter"]'::jsonb, 0, 'Under AU-C 265.12, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the release of the auditor''s report on the financial statements. Choice B is incorrect because the standard ties the deadline to the report release date, not to the date of identification during fieldwork, allowing the auditor to complete the evaluation before issuing the communication.', 'easy', 1),

-- Q30: hard / L4 — Evaluate classification of combined significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redwood Financial Services Corp., the engagement team identifies three control deficiencies: (1) the accounting manager does not review journal entries exceeding $10,000, (2) bank reconciliations are prepared but not reviewed by an independent party, and (3) access to the general ledger system is not restricted to authorized personnel. Individually, each deficiency was classified as a significant deficiency. Materiality is $300,000, and the company processes $12 million in annual transactions. The auditor should evaluate whether:', '["The three deficiencies should remain classified as individual significant deficiencies because each was already assessed independently", "The combination of the three deficiencies constitutes a material weakness because together they affect the entity''s ability to prevent or detect material misstatements across the initiation, recording, and review of financial transactions", "Only the journal entry review deficiency requires escalation because it directly affects the financial statements", "The deficiencies should be communicated to management as other control deficiencies rather than significant deficiencies"]'::jsonb, 1, 'Under AU-C 265.A12, the auditor evaluates whether individually significant deficiencies, in combination, represent a material weakness. These three deficiencies—unreviewed entries, unreviewed reconciliations, and unrestricted system access—collectively undermine the entire transaction cycle from initiation through recording and review, creating a reasonable possibility of undetected material misstatement. Choice A is incorrect because the auditor must assess the combined effect of related deficiencies rather than limiting the evaluation to each deficiency in isolation.', 'hard', 4)
;

COMMIT;
